"""Integrated scenario/report producer; run from run-all build directory."""
import csv,html,json,sys
from pathlib import Path
from datetime import date
from model import ROOT,K,D,load,run,experiments,window

def add_months(day,n):
 import calendar
 d=D(day);m=d.year*12+d.month-1+n;y,m=divmod(m,12);m+=1
 return date(y,m,min(d.day,calendar.monthrange(y,m)[1])).isoformat()
def delivery(rows,results,milestones,midterm):
 table=[];specific={r['policy']:r for r in milestones};aliases={'HLT-5':'HLT-3'}
 for row in rows:
  i=row['id'];rail=row['rail']
  if rail not in ('R1','R2','R3','FLOOR') or i=='D2-RULES':continue
  spec=specific.get(i,{});pkg=spec.get('package') or (rail if rail.startswith('R') else aliases.get(i,i));dates={};statuses={}
  lag=int(float(row['felt_months']))
  for r in results:
   key=str(r['run_id']);completed=r['scope_completion'].get(pkg);effect=None
   if completed:effect=max(add_months(completed,lag),spec.get('not_before') or completed)
   dates[key]=effect
   statuses[key]='not_modeled' if completed is None else 'governed_after_midterm' if spec.get('not_before','')>midterm else 'candidate_under_legacy_lag' if effect<=midterm else 'after_midterm_under_legacy_lag'
  table.append(dict(policy=i,package=pkg,source=row['source'],legacy_lag_months=lag,not_before=spec.get('not_before') or None,scope_limit=spec.get('scope_limit') or 'Initial effect under unvalidated legacy lag; not full implementation',requirements=spec.get('requirements') or 'Effective dates; agency capacity; rules; state/private participation; reach and measurement remain to be specified',candidate_dates=dates,statuses=statuses,validation='Unverified: opportunity screen, not projected or observed household receipt'))
 return table

def main(out=Path('.')):
 c,rows=load();results=experiments(c);out.mkdir(exist_ok=True,parents=True)
 meta=dict(schema_version=2,policy_source_commit=c['source_commit'],assumption_status=c['status'],method='scenario analysis; no probabilities or automatic scope adoption',scope_count=sum(bool(i['scope']) for i in c['items']),midterm=c['midterm'])
 health_development=dict(status='Development approved; earlier launch dates not adopted',canonical='../domains/domain-health.md#earlier-delivery-alternatives-development-approved-october-23',evidence='../sources/health-2029-restoration-and-2030-medicare-option.md',restoration='Develop component-specific 2029 delivery; retain adopted 2030 baseline pending selection',hearing_vision='Develop January 2030 option; retain 2031 fallback; compare summer R2 with earlier preparation against possible R1 authority',limits='No new CMS critical path or incremental score; 24-month legacy lag is not a verified minimum; dental and HLT-3 dates unchanged')
 data=dict(meta=meta,config=c,runs=results,development={'health':health_development})
 ledger_path=Path('ledger.json')
 if ledger_path.exists():
  ledger=json.loads(ledger_path.read_text());data['ledger']={'summary':ledger['summary'],'bills':ledger['bills']}
 (out/'calendar-scenarios.json').write_text(json.dumps(data,separators=(',',':'))+'\n')
 with (ROOT/'legacy/sources/calendar-delivery-milestones.csv').open() as f:milestones=list(csv.DictReader(f))
 effects=delivery(rows,results,milestones,c['midterm'])
 (out/'calendar-delivery.json').write_text(json.dumps(dict(meta=meta,policies=effects,development={'health':health_development}),separators=(',',':'))+'\n')
 lines=['# Calendar scenarios: demand, capacity and strategy','', '**Integrated method; illustrative, uncalibrated numbers.** These are conditional procedural completions assuming votes, eligibility and bicameral agreement. They are not enactment probabilities or household-impact forecasts. The old 172/163 comparison remains a legacy crosswalk, not the governing capacity constraint.','', 'Generated by models/tools/calendar/build.py from the live bill inventory and calendar-scenarios.json inputs. See legacy/sources/calendar-model-review-and-integration.md for changes, assumptions, source limits and priorities.','', '## Full-scope demand envelope','', '| Condition | Senate active hours | Eight-hour equivalents | House hours | Full climate merger change, Senate hours |','| --- | ---: | ---: | ---: | ---: |']
 for k in K:
  a,_=run(c,k);b,_=run(c,k,merged=True);lines.append(f"| {k} | {a['demand_hours']['S']} | {a['demand_hours']['S']/8:.1f} | {a['demand_hours']['H']} | {b['demand_hours']['S']-a['demand_hours']['S']:+} |")
 lines += ['', 'Eight-hour equivalents are work normalization, not actual sitting dates. Procedural sitting spans, readiness, House work, other business and reserve are separate. MOV floor time in the second Congress remains unknown.','', '## Deadline-led strategy with opening concentration','', '| Conditions | Capacity | Separate / combined | Net Senate hours | Original scope completed | Checks missed | DEM recovery decision required |','| --- | --- | --- | ---: | ---: | --- | --- |']
 for a in results:
  if a['strategy']=='deadline' and a['frontload'] and not a['shock']:
   lines.append(f"| {a['condition']} | {a['capacity']} | {'combined' if a['merged'] else 'separate'} | {a['usage']['S']['net']:.1f} | {a['scope_completed']}/{a['scope_total']} | {', '.join(a['deadline_misses']) or 'None'} | {a['DEM_recovery_decision_required']} |")
 lines += ['', 'Scope counts retain the two original climate identifiers after merging; they are not public-value weights. The comparison screen uses each package date and protected timing check separately, with no more gross resource use. No automatic best policy is selected.','', '## Timing definitions','', '- DEM March is a floor-start check; spring enactment and the June outer check remain separate. An after-R1 recovery needs an explicit decision, not an automatic postponement.', '- Month targets use their final date; spring and summer remain windows. No arbitrary day 28 is assigned. Spring SS uses a March–May modeling convention, not a newly adopted exact deadline.', '- Both chambers have independent capacity. Opening concentration adds hours and shifts other business, with every shifted hour charged back later.', '- Explicit hypothetical blackouts replace closing August and December wholesale. These are experiments, not future congressional schedules.', '- Vote and fiscal inputs are unchanged. Calendar completion is not multiplied into war-game vote probabilities.', '', '## Delivery is separate','', 'See [delivery opportunities](calendar-delivery-opportunities.md) and [scenario explorer](calendar-scenario-explorer.html). Earlier completion can create implementation time; legal start dates, capacity, uptake and relief still determine whether anyone benefits. All legacy felt-by-midterm labels are now explicitly unverified.']
 (out/'calendar-scenarios.md').write_text('\n'.join(lines)+'\n')
 choices=[a for a in results if a['strategy']=='deadline' and a['capacity']=='working' and not a['merged'] and a['frontload'] and not a['shock']]
 ref={a['condition']:str(a['run_id']) for a in choices}
 dl=['# Possible effects before the 2030 midterms','', '**Opportunity screen, not a forecast.** Dates below add each policy’s existing, unvalidated felt-month lag to conditional package completion, respecting the named adopted not-before dates. This does not certify delivery, change launch dates or rephase fiscal/household models. A candidate means the arithmetic permits an initial effect; it does not establish reach, magnitude, legality, operational readiness or attribution.','', 'The optimistic implication is plausible as a research direction: early benefits, legal protections and initial service phases may have more time to operate. The public plan (2031), its auto-enrollment (2032), Medicare hearing/vision (2031), dental (2033) and the first SS benefit COLA (2031) are not pulled into 2030 by this exercise.','', '| Policy | Package | Existing lag, months | Favorable opportunity date | Central opportunity date | Adopted floor / scope limitation | Required delivery work |','| --- | --- | ---: | --- | --- | --- | --- |']
 for e in effects:
  dl.append(f"| {e['policy']} | {e['package']} | {e['legacy_lag_months']} | {(e['candidate_dates'].get(ref['favorable']) or 'Not modeled')[:7]} | {(e['candidate_dates'].get(ref['central']) or 'Not modeled')[:7]} | {e['not_before'] or 'No date verified'}; {e['scope_limit']} | {e['requirements']} |")
 dl += ['', '## Focused evidence and health acceleration', '', 'See [opening procedural packet](../sources/calendar-opening-procedural-packet.md), [priority delivery paths](../sources/calendar-2030-delivery-paths.md) and [2029 restoration / 2030 hearing-vision option](../sources/health-2029-restoration-and-2030-medicare-option.md). The 24-month HLT-2 lag is not a verified minimum; midyear existing-program restoration has precedent. Development of these alternatives is approved. Accelerated dates remain proposals; this generated screen preserves the adopted baseline. Canonical options: [health domain](../domains/domain-health.md#earlier-delivery-alternatives-development-approved-october-23). Next work: component-level delivery schedule and incremental cost/financing bridge, including FY2029 administration and CAP overlap.', '', '## What to investigate first','', '1. Monthly CTC and health restoration: earliest lawful first receipt, non-filer/coverage reach, IRS/CMS/state readiness and real staffing/cash.','2. R2 initial services: school meals, pre-K/lowest-income care, dividend, housing and wage-transition dependencies; distinguish tax-year rules, initial access and full rollout.','3. Early protections: reproductive/civil rights, executive guardrails, ethics and registration can matter before a new national benefit system matures; identify enforceable dates, courts, remedies and who can actually use them.','4. SS and new health benefits: preserve adopted start dates; distinguish assurance of future solvency from a current household payment.','', 'The legacy lag is an assumption, not an agency implementation plan. No count of candidate policies is presented as a count of proven benefits or electoral effects. Source: live ledger-bills.csv and legacy/sources/calendar-delivery-milestones.csv; canonical references are retained per row.']
 (out/'calendar-delivery-opportunities.md').write_text('\n'.join(dl)+'\n')
 # Self-contained HTML with text-only DOM insertion for source-derived values.
 template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project 2050 calendar scenarios</title><style>body{font:16px system-ui;background:#f3f5f2;color:#19313b;margin:24px auto;max-width:1150px;padding:18px}p{line-height:1.5}.notice{background:#ffedc3;padding:16px}select{font:inherit;padding:8px;margin:8px}table{border-collapse:collapse;background:white;width:100%}td,th{border-bottom:1px solid #ddd;text-align:left;padding:10px}.scroll{overflow:auto}label{display:inline-block}h1{font-size:32px}</style><h1>Project 2050: agenda dashboard</h1><p>Current ledger, scenario calendar and delivery evidence. Fiscal amounts use the existing adopted model; the surge cash proxy remains unvalidated.</p><h2>Master ledger</h2><p id="fiscal"></p><label>Find a policy <input id="search" type="search" placeholder="Policy ID, name or vehicle"></label><div class="scroll"><table><thead><tr><th>Policy</th><th>Bill / title</th><th>Vehicle</th><th>GF midpoint, $T</th><th>Felt evidence</th></tr></thead><tbody id="ledger"></tbody></table></div><h2>Calendar scenarios</h2><p class="notice">Illustrative, uncalibrated inputs. Completion assumes votes and final agreement. These are not enacted policy, probabilities or felt-impact forecasts. All original scope stays visible.</p><div id="controls"></div><p id="summary"></p><p id="checks"></p><h2>Conditional dates</h2><div class="scroll"><table><thead><tr><th>Vehicle</th><th>Senate start</th><th>Completion</th></tr></thead><tbody id="dates"></tbody></table></div><h2>Strategy comparison</h2><p>Frontier means no tested alternative improves a package date or timing check without worsening another or using more gross chamber hours. It is not a readiness score.</p><div class="scroll"><table><thead><tr><th>Strategy</th><th>Climate</th><th>Opening concentration</th><th>Original scope</th><th>Missed checks</th><th>Frontier</th></tr></thead><tbody id="compare"></tbody></table></div><h2>Health acceleration: development approved</h2><p>Develop component-specific 2029 restoration and a January 2030 Medicare hearing/vision option. Existing launch dates and all financial inputs remain the baseline. The 24-month legacy lag is not a verified CMS minimum. No new CMS launch plan or incremental score is complete.</p><p><a href="../domains/domain-health.md#earlier-delivery-alternatives-development-approved-october-23">Canonical health alternatives</a> · <a href="../sources/health-2029-restoration-and-2030-medicare-option.md">Evidence and next work</a> · <a href="calendar-delivery-opportunities.md">Delivery opportunities</a> · <a href="2029-trifecta-master-ledger.md">Master ledger</a></p><h2>Delivery</h2><p>Earlier passage creates opportunity, not proof of receipt. See calendar-delivery-opportunities.md. HLT-3’s 2031/2032 dates remain fixed. Five-sitting F spans and minority guarantees remain; blackout dates and capacity assumptions need calibration.</p><script>const DATA=__DATA__;const Q={condition:['favorable','central','difficult'],capacity:['constrained','working','expanded'],strategy:['deadline','dependency','quick','large'],merged:['false','true'],frontload:['false','true']};const el=i=>document.getElementById(i);for(const [id,vs]of Object.entries(Q)){const lab=document.createElement('label');lab.textContent=id;const s=document.createElement('select');s.id=id;for(const v of vs){const o=document.createElement('option');o.value=o.textContent=v;s.append(o)}s.value=({condition:'central',capacity:'working',strategy:'deadline',merged:'false',frontload:'true'})[id];s.addEventListener('change',draw);lab.append(s);el('controls').append(lab)}function rows(id,rs){el(id).replaceChildren();for(const r of rs){const tr=document.createElement('tr');for(const v of r){const td=document.createElement('td');td.textContent=v;tr.append(td)}el(id).append(tr)}}function draw(){const v=Object.fromEntries(Object.keys(Q).map(i=>[i,el(i).value]));const a=DATA.runs.find(r=>!r.shock&&Object.keys(Q).every(k=>String(r[k])===v[k]));el('summary').textContent=`Original scope completed conditionally: ${a.scope_completed}/${a.scope_total}. Senate active demand ${a.demand_hours.S} h; net capacity ${a.usage.S.net} h; span-blocked ${a.usage.S.span_blocked} h. DEM recovery decision required: ${a.DEM_recovery_decision_required}.`;el('checks').textContent='Missed timing checks: '+(a.deadline_misses.join(', ')||'none');rows('dates',Object.entries(a.vehicles).map(([i,s])=>[i,s.S_start||'Not reached',s.done||'Unfinished']));rows('compare',DATA.runs.filter(r=>!r.shock&&r.condition===v.condition&&r.capacity===v.capacity).map(r=>[r.strategy,r.merged?'Combined full scope':'Separate',String(r.frontload),`${r.scope_completed}/${r.scope_total}`,r.deadline_misses.join(', ')||'None',String(r.on_frontier)]))}function showLedger(){if(!DATA.ledger)return;const s=DATA.ledger.summary;el('fiscal').textContent=`General-fund claims $${s.gf_claims.mid.toFixed(2)}T; base $${s.base_revenue.mid.toFixed(2)}T; residual after accepted measures $${s.gap_after_accepted.toFixed(2)}T. Calendar results do not rephase fiscal or household inputs.`;const q=el('search').value.toLowerCase();rows('ledger',DATA.ledger.bills.filter(b=>[b.id,b.bill,b.rail].join(' ').toLowerCase().includes(q)).map(b=>[b.id,b.bill,b.rail,b.gf_mid.toFixed(3),b.felt_by_midterm]))}el('search').addEventListener('input',showLedger);draw();showLedger();</script></html>'''
 (out/'calendar-scenario-explorer.html').write_text(template.replace('__DATA__',json.dumps(data,separators=(',',':')).replace('</','<\\/')))
 print(f'calendar: {len(results)} conditional cases; {len(effects)} policy delivery screens; all illustrative')
if __name__=='__main__':main(Path(sys.argv[1]) if len(sys.argv)>1 else Path('.'))
